async function issueHrefById(
  orgId: OrgId,
  orgSlug: string,
  issueId: Issue["id"],
): Promise<string> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  const project = issue
    ? await projectRepo.findProjectById(orgId, issue.projectId)
    : null;
